document.addEventListener('DOMContentLoaded',()=>{const navToggle=document.getElementById('nav-toggle');if(navToggle){document.querySelectorAll('.mobile-drawer a').forEach((link)=>{link.addEventListener('click',()=>{navToggle.checked=false;});});document.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&navToggle.checked){navToggle.checked=false;}});}const menuRoot=document.querySelector('[data-menu-filter-root]');if(menuRoot){const searchInput=menuRoot.querySelector('[data-menu-search]');const catButtons=Array.from(menuRoot.querySelectorAll('[data-menu-cat]'));const tagButtons=Array.from(menuRoot.querySelectorAll('[data-menu-tag]'));const clearButtons=Array.from(document.querySelectorAll('[data-menu-clear]'));const itemEls=Array.from(document.querySelectorAll('[data-menu-item]'));const catSections=Array.from(document.querySelectorAll('[data-menu-category-section]'));const emptyState=document.getElementById('menu-empty-state');let activeCategory='all';const activeTags=new Set();const applyFilters=()=>{const query=(searchInput?searchInput.value:'').trim().toLowerCase();let visibleItems=0;itemEls.forEach((itemEl)=>{const itemCat=itemEl.dataset.category||'';const itemTags=(itemEl.dataset.tags||'').split(',').filter(Boolean);const itemSearch=itemEl.dataset.search||'';const matchesCat=activeCategory==='all'||itemCat===activeCategory;const matchesSearch=query===''||itemSearch.includes(query);const matchesTags=Array.from(activeTags).every((tag)=>itemTags.includes(tag));const visible=matchesCat&&matchesSearch&&matchesTags;itemEl.style.display=visible?'':'none';if(visible){visibleItems++;}});catSections.forEach((section)=>{const hasVisible=Array.from(section.querySelectorAll('[data-menu-item]')).some((el)=>el.style.display!=='none');section.style.display=hasVisible?'':'none';});if(emptyState){emptyState.style.display=visibleItems===0?'block':'none';}};if(searchInput){searchInput.addEventListener('input',applyFilters);}catButtons.forEach((btn)=>{btn.addEventListener('click',()=>{activeCategory=btn.dataset.menuCat||'all';catButtons.forEach((b)=>b.classList.toggle('is-active',b===btn));applyFilters();});});tagButtons.forEach((btn)=>{btn.addEventListener('click',()=>{const slug=btn.dataset.menuTag||'';if(activeTags.has(slug)){activeTags.delete(slug);btn.classList.remove('is-active');btn.setAttribute('aria-pressed','false');}else{activeTags.add(slug);btn.classList.add('is-active');btn.setAttribute('aria-pressed','true');}applyFilters();});});clearButtons.forEach((btn)=>{btn.addEventListener('click',()=>{if(searchInput){searchInput.value='';}activeCategory='all';activeTags.clear();catButtons.forEach((b)=>b.classList.toggle('is-active',b.dataset.menuCat==='all'));tagButtons.forEach((b)=>{b.classList.remove('is-active');b.setAttribute('aria-pressed','false');});applyFilters();});});}document.querySelectorAll('[data-copy-code]').forEach((chip)=>{chip.addEventListener('click',async()=>{const code=chip.dataset.copyCode||'';if(!code){return;}try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(code);}else{const tmp=document.createElement('textarea');tmp.value=code;tmp.style.position='fixed';tmp.style.opacity='0';document.body.appendChild(tmp);tmp.select();document.execCommand('copy');document.body.removeChild(tmp);}const statusEl=chip.querySelector('[data-copy-status]');chip.classList.add('is-copied');if(statusEl){statusEl.textContent='Copied!';}setTimeout(()=>{chip.classList.remove('is-copied');if(statusEl){statusEl.textContent='Tap to copy';}},2000);}catch{}});});document.querySelectorAll('[data-youtube-id]').forEach((facadeBtn)=>{facadeBtn.addEventListener('click',()=>{const videoId=facadeBtn.dataset.youtubeId||'';if(!/^[a-zA-Z0-9_-]{11}$/.test(videoId)){return;}const frameContainer=facadeBtn.closest('.media-frame');if(!frameContainer){return;}const iframe=document.createElement('iframe');iframe.src=`https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0`;iframe.title=facadeBtn.getAttribute('aria-label')||'Renzo Video';iframe.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture';iframe.allowFullscreen=true;frameContainer.replaceChildren(iframe);});});const lightbox=document.getElementById('gallery-lightbox');const photoTriggers=Array.from(document.querySelectorAll('[data-lightbox-trigger]'));if(lightbox&&photoTriggers.length>0){const imgEl=lightbox.querySelector('[data-lightbox-img]');const titleEl=lightbox.querySelector('[data-lightbox-title-el]');const captionEl=lightbox.querySelector('[data-lightbox-caption-el]');let currentIndex=0;const openAt=(index)=>{currentIndex=(index+photoTriggers.length)%photoTriggers.length;const trigger=photoTriggers[currentIndex];if(imgEl){imgEl.src=trigger.dataset.lightboxSrc||'';imgEl.alt=trigger.dataset.lightboxTitle||'Renzo photo';}if(titleEl){titleEl.textContent=trigger.dataset.lightboxTitle||'';}if(captionEl){captionEl.textContent=trigger.dataset.lightboxCaption||'';}lightbox.hidden=false;};const closeBox=()=>{lightbox.hidden=true;if(imgEl){imgEl.src='';}};photoTriggers.forEach((btn,idx)=>{btn.addEventListener('click',()=>openAt(idx));});lightbox.querySelectorAll('[data-lightbox-close]').forEach((el)=>{el.addEventListener('click',closeBox);});const prevBtn=lightbox.querySelector('[data-lightbox-prev]');const nextBtn=lightbox.querySelector('[data-lightbox-next]');if(prevBtn){prevBtn.addEventListener('click',()=>openAt(currentIndex-1));}if(nextBtn){nextBtn.addEventListener('click',()=>openAt(currentIndex+1));}document.addEventListener('keydown',(event)=>{if(lightbox.hidden){return;}if(event.key==='Escape'){closeBox();}else if(event.key==='ArrowLeft'){openAt(currentIndex-1);}else if(event.key==='ArrowRight'){openAt(currentIndex+1);}});}const addVariantBtn=document.querySelector('[data-add-variant]');const variantsBox=document.querySelector('[data-variants-container]');if(addVariantBtn&&variantsBox){let nextVariantIndex=variantsBox.querySelectorAll('[data-variant-row]').length;variantsBox.addEventListener('click',(event)=>{const removeBtn=event.target.closest('[data-remove-variant]');if(removeBtn){const row=removeBtn.closest('[data-variant-row]');if(row){row.remove();}}});addVariantBtn.addEventListener('click',()=>{const index=nextVariantIndex++;const row=document.createElement('div');row.className='form-grid';row.setAttribute('data-variant-row','1');row.innerHTML=`
                <div class="field">
                    <label>Variant Name</label>
                    <input type="text" name="variant_name[${index}]" placeholder="e.g. Large">
                </div>
                <div class="field">
                    <label>Price</label>
                    <input type="number" step="0.01" min="0" name="variant_price[${index}]" placeholder="0.00">
                </div>
                <div class="field" style="display:flex;align-items:center;gap:10px;padding-top:24px;">
                    <label style="margin:0;"><input type="checkbox" name="variant_available[${index}]" value="1" checked> Available</label>
                    <button type="button" class="btn btn-danger btn-sm" data-remove-variant>Remove</button>
                </div>
            `;variantsBox.appendChild(row);});}});